import java.io.IOException;
import java.nio.IntBuffer;
import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;
import org.lwjgl.PointerBuffer;
import org.lwjgl.system.MemoryStack;
import org.lwjgl.util.lmdb.MDBVal;

class LmdbMainDatabaseOpenContractTest {

	@Test
	void unnamedMainDatabaseExistsWithoutAWriterAndCreateOpenDoesNotOwnACommit(
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			long environment = handle.get(0);
			try {
				E(mdb_env_open(environment, directory.toString(), MDB_NOTLS, 0664));
				long initial = LmdbUtil.readTransaction(environment, (memory, txn) -> {
					mainDatabase(memory, txn, 0);
					return mdb_txn_id(txn);
				});
				byte[] before = Files.readAllBytes(directory.resolve("data.mdb"));
				long noOpCandidate = LmdbUtil.writeTransaction(environment, (memory, txn) -> {
					mainDatabase(memory, txn, MDB_CREATE);
					return mdb_txn_id(txn);
				});
				long afterNoOp = LmdbUtil.readTransaction(environment, (memory, txn) -> mdb_txn_id(txn));
				assertEquals(initial, afterNoOp, "opening the unnamed database needs no bootstrap commit");
				assertArrayEquals(before, Files.readAllBytes(directory.resolve("data.mdb")));
				long laterWriter = LmdbUtil.writeTransaction(environment, (memory, txn) -> {
					int main = mainDatabase(memory, txn, 0);
					MDBVal key = MDBVal.calloc(memory).mv_data(memory.bytes((byte) 1));
					MDBVal value = MDBVal.calloc(memory).mv_data(memory.bytes((byte) 2));
					E(mdb_put(txn, main, key, value, 0));
					return mdb_txn_id(txn);
				});
				assertEquals(noOpCandidate, laterWriter,
						"a later real writer can consume the uncommitted candidate ID of a no-op writer");
				Files.writeString(directory.resolve("native-main-contract.txt"),
						mdb_version((IntBuffer) null, null, null) + "\ninitial=" + initial + "\nnoOpCandidate=" + noOpCandidate
								+ "\nafterNoOp=" + afterNoOp + "\nlaterWriter=" + laterWriter + "\n");
			} finally {
				mdb_env_close(environment);
			}
		}
	}

	private static int mainDatabase(MemoryStack stack, long txn, int flags) throws IOException {
		IntBuffer database = stack.mallocInt(1);
		assertEquals(MDB_SUCCESS, mdb_dbi_open(txn, (String) null, flags, database),
				"the unnamed main database must exist even before the first native writer");
		return database.get(0);
	}
}
